namespace ZapretManager {
public class Sample { public string Target,Error="";public bool Core,Success,Unknown;public int Http;public double Seconds; }
public class Measurement {public List<Sample> Samples=new List<Sample>();public int Good {get{return Samples.Count(s=>s.Success);}}public int Media {get{return Samples.Count(s=>s.Target.StartsWith("Discord media")&&s.Success);}}public bool Valid {get{return Samples.Any(s=>s.Core)&&Samples.All(s=>!s.Core||s.Success)&&!Samples.Any(s=>s.Target.StartsWith("Discord media")&&!s.Success&&!s.Unknown);}}public double Median {get{return Quantile(.5);}}public double P90 {get{return Quantile(.9);}} double Quantile(double f){var t=Samples.Where(s=>s.Success&&s.Seconds>0).Select(s=>s.Seconds).OrderBy(x=>x).ToArray();return t.Length==0?6:t[(int)Math.Floor((t.Length-1)*f)];}}
public class Candidate {public string Id,Name,Error;public string[] Lua;public Measurement Measurement;}
public class FaceRow {public string Name{get;set;}public string Address{get;set;}public string Ping{get;set;}public string Loss{get;set;}public string Result{get;set;}public string Kind{get;set;}}
public static class Network {
 static string Curl {get{return Path.Combine(Environment.SystemDirectory,"curl.exe");}}
 public static async Task<Sample> Http(string name,string url,string kind,bool core,CancellationToken token,string proxy=null) {
  string body=Core.PathOf("native-probe-"+Guid.NewGuid().ToString("N")+".body");var s=new Sample {Target=name,Core=core,Seconds=6};
  try {string args=(proxy==null?"--noproxy \"*\"":"--noproxy \"\" --proxy "+Core.Quote("http://"+proxy))+" --http1.1 --tlsv1.2 -sS -L --connect-timeout 3 --max-time 6 -H \"Cache-Control: no-cache\" -o "+Core.Quote(body)+" -w \"%{http_code} %{time_total}\" "+Core.Quote(url);var r=await Core.Run(Curl,args,token,9000);var p=r.Output.Trim().Split(' ');int code;double seconds;if(p.Length>=2&&int.TryParse(p[0],out code)&&double.TryParse(p[1],System.Globalization.NumberStyles.Float,System.Globalization.CultureInfo.InvariantCulture,out seconds)){s.Http=code;s.Seconds=seconds;}
   s.Success=r.Exit==0&&(kind=="empty"?s.Http==204:kind=="cdn"?new[]{200,403,404}.Contains(s.Http):kind=="any"?s.Http>0:s.Http==200);s.Error=r.Error.Trim();
   if(s.Success&&kind=="youtube")s.Success=Regex.IsMatch(File.ReadAllText(body),"ytInitial|INNERTUBE|youtube");
   if(s.Success&&kind=="jpeg"){var b=File.ReadAllBytes(body);s.Success=b.Length>1000&&b[0]==255&&b[1]==216;}
   if(s.Success&&kind=="oidc"){try {var o=Core.Read<Dictionary<string,object>>(body);s.Success=(string)o["issuer"]=="https://api.faceit.com/auth"&&((string)o["token_endpoint"]).StartsWith("https://api.faceit.com/");}catch{s.Success=false;}}
   if(s.Success&&kind=="gateway"){try {var o=Core.Read<Dictionary<string,object>>(body);s.Success=((string)o["url"]).StartsWith("wss://");}catch{s.Success=false;}}
  }catch(OperationCanceledException){throw;}catch(Exception e){s.Error=e.Message;}finally{if(File.Exists(body))File.Delete(body);}return s;
 }
 public static string FaceitHttpResult(Sample s,bool transportOnly) {
  if(s.Http==0)return "Нет HTTPS-ответа: "+s.Error;
  if(s.Http==404)return transportOnly?"HTTPS доступен; у корня службы нет страницы (404). Работа Anti-Cheat не проверена":"HTTPS доступен; страница не найдена (404). Проверка сервиса не пройдена";
  if(s.Http==401)return "HTTPS доступен; требуется авторизация (401). Доступ аккаунта не проверен";
  if(s.Http==403)return "HTTPS доступен; запрос отклонён (403), возможна защита от ботов. Доступ в браузере не проверен";
  if(s.Http==429)return "HTTPS доступен; лимит запросов (429). Повторите позже";
  if(s.Http>=500)return "HTTPS доступен; ошибка сервера HTTP "+s.Http;
  if(!s.Success)return "Проверка не пройдена: HTTP "+s.Http+"; "+(string.IsNullOrWhiteSpace(s.Error)?"неожиданное содержимое ответа":s.Error);
  return transportOnly?"HTTPS доступен (HTTP "+s.Http+"); работа Anti-Cheat не проверена":"Проверка HTTPS пройдена: HTTP "+s.Http;
 }
 public static async Task<Sample> Quic(CancellationToken token) {
  var w=Stopwatch.StartNew();var s=new Sample {Target="YouTube QUIC HTTP/3 direct",Core=true};
  try {var r=await Core.Run(Core.PathOf("http3\\usr\\local\\bin\\curl.exe"),"--noproxy www.youtube.com --http3-only --connect-timeout 3 --max-time 8 -sS -o /dev/null -w \"%{http_code} %{http_version}\" --cacert "+Core.Quote(Core.PathOf("http3\\ca-bundle.crt"))+" https://www.youtube.com/",token,11000,Core.PathOf("http3\\bin"));s.Success=r.Exit==0&&r.Output.Trim()=="200 3";s.Error=r.Error;}catch(OperationCanceledException){throw;}catch(Exception e){s.Error=e.Message;}s.Seconds=w.Elapsed.TotalSeconds;return s;
 }
 public static async Task<IPAddress> Resolve(string host) {var task=Dns.GetHostAddressesAsync(host);if(await Task.WhenAny(task,Task.Delay(2500))!=task)throw new TimeoutException("DNS timeout");var ip=(await task).FirstOrDefault(a=>a.AddressFamily==AddressFamily.InterNetwork);if(ip==null)throw new Exception("Нет IPv4");return ip;}
 public static async Task<Sample> Stun(string host,int port,CancellationToken token) {
  var s=new Sample {Target="UDP STUN direct: "+host};var w=Stopwatch.StartNew();try{token.ThrowIfCancellationRequested();var ip=await Resolve(host);using(var u=new UdpClient()){u.Connect(ip,port);byte[] b=new byte[20];b[1]=1;b[4]=0x21;b[5]=0x12;b[6]=0xA4;b[7]=0x42;byte[] transaction=new byte[12];using(var rng=RandomNumberGenerator.Create()){rng.GetBytes(transaction);}Array.Copy(transaction,0,b,8,12);await u.SendAsync(b,b.Length);var receive=u.ReceiveAsync();if(await Task.WhenAny(receive,Task.Delay(2200,token))!=receive){token.ThrowIfCancellationRequested();s.Error="Нет STUN-ответа";}else{byte[] a=(await receive).Buffer;s.Success=a.Length>=20&&a[0]==1&&a[1]==1&&a.Length-20==256*a[2]+a[3]&&a.Skip(4).Take(16).SequenceEqual(b.Skip(4));}}}catch(OperationCanceledException){throw;}catch(Exception e){s.Error=e.Message;}s.Seconds=w.Elapsed.TotalSeconds;return s;
 }
 public static async Task<Measurement> Measure(int rounds,CancellationToken token) {
  var m=new Measurement();for(int i=0;i<rounds;i++){token.ThrowIfCancellationRequested();m.Samples.AddRange(await Task.WhenAll(Http("YouTube","https://www.youtube.com/","youtube",true,token),Http("YouTube images","https://i.ytimg.com/vi/dQw4w9WgXcQ/hqdefault.jpg","jpeg",true,token),Http("YouTube API","https://youtubei.googleapis.com/generate_204","empty",true,token),Http("Discord Gateway","https://discord.com/api/v10/gateway","gateway",true,token),Http("Discord CDN (TLS)","https://cdn.discordapp.com/","cdn",false,token)));}
  m.Samples.AddRange(await Task.WhenAll(Quic(token),Stun("stun.l.google.com",19302,token),Stun("stun.cloudflare.com",3478,token)));
  return m;
 }
 public static Candidate[] Candidates() {return new[]{
  new Candidate {Id="current",Name="Текущая рабочая",Lua=new string[0]},new Candidate {Id="udp-2",Name="Текущая TLS + UDP repeats 2",Lua=new string[0]},new Candidate {Id="udp-6",Name="Текущая TLS + UDP repeats 6",Lua=new string[0]},
  new Candidate {Id="split",Name="Multisplit 1 + midsld",Lua=new[]{"--lua-desync=multisplit:pos=1,midsld"}},new Candidate {Id="disorder",Name="Multidisorder midsld",Lua=new[]{"--lua-desync=multidisorder:pos=midsld"}},
  new Candidate {Id="fake-md5",Name="Fake MD5 + disorder",Lua=new[]{"--lua-desync=fake:blob=fake_default_tls:tcp_md5:tcp_seq=-10000:repeats=6","--lua-desync=multidisorder:pos=1,midsld"}},
  new Candidate {Id="fake-ts",Name="Fake TS + split",Lua=new[]{"--lua-desync=fake:blob=tls_max:tcp_ts=-600000:tcp_ts_up:repeats=4","--lua-desync=multisplit:pos=1:seqovl=480:seqovl_pattern=stun2:tcp_ts_up"}},
  new Candidate {Id="host-ts",Name="HostFakeSplit TS",Lua=new[]{"--lua-desync=hostfakesplit:host=www.google.com:tcp_ts=-600000:tcp_ts_up:ip_id=0"}},new Candidate {Id="host-seq",Name="HostFakeSplit badseq",Lua=new[]{"--lua-desync=hostfakesplit:host=www.google.com:tcp_seq=-10000:tcp_md5"}}
 };}
 public static string TuneBase(string text,Candidate c) {if(c.Id=="current")return text;if(c.Id.StartsWith("udp-"))return Regex.Replace(text,@"(?m)(--lua-desync=fake:blob=(?:quic_google|discord_udp):repeats=)4\b",m=>m.Groups[1].Value+c.Id.Substring(4));var sections=Regex.Split(text,@"(?m)^\s*--new\s*$");int changed=0;for(int i=0;i<sections.Length;i++)if(sections[i].Contains("--filter-l7=tls")&&sections[i].Contains("--payload=tls_client_hello")){sections[i]=Regex.Replace(sections[i],@"(?m)^\s*--lua-desync=[^\r\n]*\r?\n?","").TrimEnd()+"\r\n"+string.Join("\r\n",c.Lua)+"\r\n";changed++;}if(changed<2)throw new Exception("Не найдены TLS-профили");return string.Join("\r\n--new\r\n",sections);}
 public static Candidate Winner(IEnumerable<Candidate> results) {
  var valid=results.Where(c=>c.Measurement!=null&&c.Measurement.Valid).ToArray();var best=valid.OrderByDescending(c=>(double)c.Measurement.Good/c.Measurement.Samples.Count).ThenBy(c=>c.Measurement.P90).ThenBy(c=>c.Measurement.Median).FirstOrDefault();var current=valid.FirstOrDefault(c=>c.Id=="current");
  if(best!=null&&current!=null&&best!=current&&(double)best.Measurement.Good/best.Measurement.Samples.Count<=(double)current.Measurement.Good/current.Measurement.Samples.Count&&best.Measurement.P90>=current.Measurement.P90-Math.Max(.05,current.Measurement.P90*.15))return current;return best;
 }
 public static Task Tune(CancellationToken token,Action<int,string> progress) {return Task.Run(()=>{using(var mutex=new Mutex(false,@"Global\Zapret2AutoTune")){bool owned=false;try{try{owned=mutex.WaitOne(0);}catch(AbandonedMutexException){owned=true;}if(!owned)throw new Exception("Подбор уже работает");TuneOwned(token,progress).GetAwaiter().GetResult();}finally{if(owned)mutex.ReleaseMutex();}}});}
 static async Task TuneOwned(CancellationToken token,Action<int,string> progress) {
  Core.Guard();var backup=Core.Backup();Core.Write(Core.PathOf("native-tune-pending.json"),backup);File.WriteAllText(Core.PathOf("autotune-pending.json"),"{\"Native\":true}");File.WriteAllText(Core.PathOf("native-last-backup.txt"),backup.Directory);
   bool safe=false;try {string original=File.ReadAllText(Path.Combine(backup.Directory,"manager-base.txt"));var settings=Core.Load();var candidates=Candidates();var measured=new List<Candidate>();
    for(int i=0;i<candidates.Length;i++){token.ThrowIfCancellationRequested();var c=candidates[i];progress(i*85/candidates.Length,"Стратегия "+(i+1)+"/"+candidates.Length+": "+c.Name);try{await Core.Apply(settings,token,TuneBase(original,c),true);if(Core.State()!="Running")Core.Control("On");await Task.Delay(1000,token);c.Measurement=await Measure(2,token);measured.Add(c);progress((i+1)*85/candidates.Length,c.Name+": "+c.Measurement.Good+"/"+c.Measurement.Samples.Count+", P90 "+c.Measurement.P90.ToString("0.000")+" с");}catch(OperationCanceledException){throw;}catch(Exception e){c.Error=e.Message;measured.Add(c);progress((i+1)*85/candidates.Length,c.Name+": "+e.Message);}Core.Write(Core.PathOf("native-autotune-results.json"),measured);}
    var best=Winner(measured);if(best==null)throw new Exception("Ни одна стратегия не прошла обязательные проверки");progress(90,"Повторная проверка финалистов");var finalists=measured.Where(c=>c.Id=="current"||c==best).ToArray();foreach(var c in finalists){await Core.Apply(settings,token,TuneBase(original,c),true);if(Core.State()!="Running")Core.Control("On");c.Measurement=await Measure(3,token);}best=Winner(finalists);if(best==null)throw new Exception("Повторная проверка не пройдена");settings.StrategyId=best.Id;settings.StrategyName=best.Name;await Core.Apply(settings,token,TuneBase(original,best),true);if(backup.State!="Running")Core.Control("Off");using(var key=Microsoft.Win32.Registry.LocalMachine.OpenSubKey(@"SYSTEM\CurrentControlSet\Services\"+Core.Service,true)){key.SetValue("Start",backup.Start);}Core.Write(Core.PathOf("native-autotune-results.json"),measured);progress(100,"Выбрана стратегия: "+best.Name);safe=true;
   }catch{Core.Restore(backup);safe=true;throw;}finally{if(safe){File.Delete(Core.PathOf("autotune-pending.json"));File.Delete(Core.PathOf("native-tune-pending.json"));}}
 }
 public static void Recover(){using(var mutex=new Mutex(false,@"Global\Zapret2AutoTune")){bool own=false;try{try{own=mutex.WaitOne(0);}catch(AbandonedMutexException){own=true;}if(!own)throw new Exception("Подбор ещё работает");string f=Core.PathOf("native-last-backup.txt");if(!File.Exists(f))throw new Exception("Резервная копия приложения отсутствует");var snap=Core.Read<Snapshot>(Path.Combine(File.ReadAllText(f).Trim(),"native-manifest.json"));Core.Restore(snap);File.Delete(Core.PathOf("autotune-pending.json"));File.Delete(Core.PathOf("native-tune-pending.json"));}finally{if(own)mutex.ReleaseMutex();}}}
 public static IPEndPoint ParseServer(string value){string v=Regex.Replace(value.Trim(),@"^connect\s+","");Match m=Regex.Match(v,@"^(\d{1,3}(?:\.\d{1,3}){3}):(\d{1,5})$");IPAddress ip;int port;if(!m.Success||!IPAddress.TryParse(m.Groups[1].Value,out ip)||!int.TryParse(m.Groups[2].Value,out port)||port<1||port>65535)throw new Exception("Введите IPv4:порт сервера матча");return new IPEndPoint(ip,port);}
 public static async Task<List<FaceRow>> Faceit(string server,CancellationToken token) {
  string[] names={"Финляндия","Германия","Швеция","Нидерланды","Франция","Великобритания","Москва","Казахстан"};string[] ids={"finland","germany","sweden","netherlands","france","uk","moscow","kazakhstan"};
  var jobs=ids.Select((id,i)=>Region(names[i],id+".eu.ping.faceit.com",token)).ToArray();var rows=(await Task.WhenAll(jobs.Concat(new[]{Region("Cloudflare DNS","1.1.1.1",token),Region("Google DNS","8.8.8.8",token)}))).ToList();
  string[] urls={"https://www.faceit.com/","https://api.faceit.com/auth/v1/openid_configuration","https://ac-client-ws.faceit.com/","https://discord.com/api/v10/gateway","https://www.youtube.com/"};string proxy=Core.Proxy();foreach(var url in urls)foreach(string mode in proxy==""?new[]{"Прямой"}:new[]{"Прямой","Proxy"}){token.ThrowIfCancellationRequested();var s=await Http(new Uri(url).Host,url,url.Contains("discord.com")?"gateway":url.Contains("youtube.com")?"youtube":url.Contains("openid_configuration")?"oidc":"any",false,token,mode=="Proxy"?proxy:null);rows.Add(new FaceRow {Name=s.Target+" · "+mode,Address=url,Ping=Math.Round(s.Seconds*1000).ToString()+" мс HTTP",Loss="—",Kind="https",Result=FaceitHttpResult(s,new Uri(url).Host=="ac-client-ws.faceit.com")});}
  if(!string.IsNullOrWhiteSpace(server)){var ep=ParseServer(server);string result="UDP без ответа; допуск в матч не установлен";var sw=Stopwatch.StartNew();using(var u=new UdpClient()){try{u.Connect(ep);var b=new byte[]{255,255,255,255,84}.Concat(Encoding.ASCII.GetBytes("Source Engine Query\0")).ToArray();for(int tries=0;tries<2;tries++){await u.SendAsync(b,b.Length);var task=u.ReceiveAsync();if(await Task.WhenAny(task,Task.Delay(2500,token))!=task){token.ThrowIfCancellationRequested();break;}var a=(await task).Buffer;if(a.Length>=6&&a.Take(4).All(x=>x==255)&&a[4]==73){result="A2S_INFO ответил; вход требует CS2 и Anti-Cheat";break;}if(a.Length==9&&a[4]==65){b=b.Concat(a.Skip(5)).ToArray();continue;}break;}}catch(OperationCanceledException){throw;}catch(Exception e){result+="; "+e.Message;}}rows.Add(new FaceRow {Name="Сервер матча",Address=ep.ToString(),Ping=Math.Round(sw.Elapsed.TotalMilliseconds)+" мс",Loss="—",Kind="game",Result=result});}Core.Write(Core.PathOf("native-faceit-results.json"),new {Date=DateTime.Now,Rows=rows});return rows;
 }
 static async Task<FaceRow> Region(string name,string host,CancellationToken token){var row=new FaceRow {Name=name,Address=host,Ping="—",Loss="—",Kind="region"};try{var ip=await Resolve(host);row.Address+=" / "+ip;var times=new List<long>();for(int n=0;n<6;n++){token.ThrowIfCancellationRequested();using(var p=new Ping()){try{var r=await p.SendPingAsync(ip,900);if(r.Status==IPStatus.Success)times.Add(r.RoundtripTime);}catch{}}await Task.Delay(150,token);}times.Sort();row.Ping=times.Count==0?"—":times[(times.Count-1)/2]+" мс";row.Loss=Math.Round((6-times.Count)*100.0/6)+"%";row.Result=times.Count==0?"ICMP не отвечает; блокировка игры не доказана":"Диагностический узел доступен; вход в матч не проверен";}catch(OperationCanceledException){throw;}catch(Exception e){row.Result="DNS: "+e.Message;}return row;}
 public static async Task FaceitUdpPreset(bool compatible,CancellationToken token){var settings=Core.Load();if(compatible){settings.GameUdpPreset="alt12-exp";settings.Game="udp";settings.IPSet="loaded";settings.FaceitServerExclusions=false;}else{settings.GameUdpPreset="native";settings.FaceitServerExclusions=true;}await Core.Apply(settings,token);}
 public static async Task ServerExclude(string server,bool exclude,CancellationToken token){Core.Guard();string ip=ParseServer(server).Address.ToString();string f=Core.PathOf("files\\faceit-game-exclude.txt");byte[] old=File.Exists(f)?File.ReadAllBytes(f):null;var ips=old==null?new List<string>():File.ReadAllLines(f).ToList();ips.RemoveAll(l=>l.Trim()==ip);if(exclude)ips.Add(ip);try{File.WriteAllLines(f,ips,Encoding.ASCII);var settings=Core.Load();settings.FaceitServerExclusions=true;await Core.Apply(settings,token);}catch{if(old==null)File.Delete(f);else File.WriteAllBytes(f,old);throw;}}
}
